rows=[]
for line in text.strip().splitlines():
    name,outcome,sales,note=line.split('|',3)
    match=[x for x in joined if x['name'].lower()==name.lower() or any(c['name'].lower()==name.lower() for c in x['contacts'])]
    if name=='Jesse Lejawka':match += [x for x in joined if x['name']=='Julie DiLiberto-Kirkelos' or x['id']=='lead_jrx77zrgf']
    ids={c['id'] for x in match for c in x['contacts']} | {c['id'] for c in contacts if c['name'].lower()==name.lower()}
    if name=='Moe':ids={c['id'] for x in match for c in x['contacts']}
    uniq=lambda a,key:{x[key]:x for x in a}.values()
    ts=list(uniq([t for t in touches if t['contact_id'] in ids],'id'))
    sm=list(uniq([s for x in match for s in x['sms']],'id'))
    cr=list(uniq([c for x in match for c in x['calls']],'recording_sid'))
    ls=[x['id'] for x in match]
    qs=[q for q in quotes if q['data'].get('leadId') in ls or any(q['id'] in [x['data'].get('quoteId'),*x['data'].get('quoteIds',[])] for x in match)]
    es=[e for e in emails if e['data'].get('leadId') in ls or any(x['data'].get('email') and e['data'].get('to','').lower()==x['data']['email'].lower() for x in match)]
    rows.append(dict(name=name,outcome=outcome,sales_evidence=sales,assessment=note,lead_ids=ls,contact_ids=list(ids),stages=[x['stage'] for x in match],owners=[x.get('assigned') for x in match],sms=sm,calls=cr,touches=ts,quotes=[dict(id=q['id'],status=q['data'].get('status'),moveDate=q['data'].get('moveDate'),total=q['data'].get('total'),depositPaidAmount=q['data'].get('depositPaidAmount'),depositPaidAt=q['data'].get('depositPaidAt')) for q in qs],emails=[dict(id=e['id'],subject=e['data'].get('subject'),status=e['data'].get('status'),sentAt=e['data'].get('sentAt')) for e in es]))
covered={i for r in rows for i in r['lead_ids']}
excluded=[]
for x in joined:
    if x['id'] in covered:continue
    reason='Relationship / generic response; no specific new moving job verified'
    if x['name'] in ['Monika Zalpiene','Jim Mcdonald','Stacey Miller','Steve Hatton','Aaron Brooks','Robert Schussler']:reason='Older relationship/job imported September 17; not a new last-30-day lead'
    if x['name']=='AURA Contracting':reason='Recurring floor-project commercial arrangement; expressly not a current customer job'
    if x['name'].lower()=='h2m staging':reason='Recurring staging rate discussion; no dated job committed'
    if x['name']=='Nadia Califf' or any(c['name']=='Mary Covemaeker' for c in x['contacts']):reason='Open-house/partner discussion incorrectly treated as a customer move'
    excluded.append(dict(name=x['name'],contacts=', '.join(c['name'] for c in x['contacts']),lead_id=x['id'],stage=x['stage'],reason=reason,latest_source=x['data'].get('notes',''),sms=x['sms'],touches=x['touches']))
counts={}
for r in rows:counts[r['outcome']]=counts.get(r['outcome'],0)+1
(p/'reviewed-opportunities.json').write_text(json.dumps(rows,indent=2))
(p/'excluded-records.json').write_text(json.dumps(excluded,indent=2))
with (p/'opportunities.csv').open('w',newline='') as f:
    w=csv.writer(f);w.writerow(['Name','Reviewed outcome','Communication evidence','Assessment / next action','Sales record IDs','CRM stages','Owners'])
    for r in rows:w.writerow([r['name'],r['outcome'],r['sales_evidence'],r['assessment'],'; '.join(r['lead_ids']),'; '.join(r['stages']),'; '.join(str(o or 'unassigned') for o in r['owners'])])
with (p/'all-sales-records.csv').open('w',newline='') as f:
    w=csv.writer(f);w.writerow(['Sales ID','Name','Partner match','Created','Stage','Deleted','Owner','Classification'])
    for x in joined:w.writerow([x['id'],x['name'],'; '.join(c['name'] for c in x['contacts']),x['created'],x['stage'],x['deleted'],x.get('assigned'),next((r['outcome'] for r in rows if x['id'] in r['lead_ids']),next(e['reason'] for e in excluded if e['lead_id']==x['id']) if x['id'] not in covered else '')])
esc=lambda x:html.escape(str(x or ''))
def clean(s):return re.sub(r'https?://\S+','[link omitted from audit excerpt]',s or '')
def evidence(r):
    events=[(s['created_at'],'Sales SMS '+s['direction'],s.get('body',''),s['id']) for s in r['sms']]
    events += [(t['created_at'],'Partnership '+t['direction'],t.get('notes',''),t['id']) for t in r['touches'] if t.get('direction') in ['inbound','outbound']]
    events += [(c['created_at'],'Call transcript',c.get('transcript') or 'Recording exists; transcript unavailable',c['recording_sid']) for c in r['calls']]
    return ''.join(f'<details><summary>{esc(at)} — {esc(kind)}</summary><p class="id">{esc(id)}</p><pre>{esc(clean(body))}</pre></details>' for at,kind,body,id in sorted(events))
cards=''.join(f'<article data-search="{esc(r["name"]+" "+r["outcome"])}"><h2>{esc(r["name"])}</h2><p><b>{esc(r["outcome"])}</b> · {esc(r["sales_evidence"])}</p><p>{esc(r["assessment"])}</p><p class="muted">CRM stages: {esc(", ".join(r["stages"]) or "No Sales match")} · Owner: {esc(", ".join(str(o or "unassigned") for o in r["owners"]))}</p><p class="id">{esc(" | ".join(r["lead_ids"]))}</p><details><summary>Review messages, calls and quote evidence</summary><pre>{esc(json.dumps(r["quotes"],indent=2))}</pre>{evidence(r)}</details></article>' for r in rows)
ex=''.join(f'<tr><td>{esc(e["name"])}<br>{esc(e["contacts"])}</td><td>{esc(e["stage"])}</td><td>{esc(e["reason"])}</td><td class="id">{esc(e["lead_id"])}</td></tr>' for e in excluded)
page='''<!doctype html><html><meta charset="utf-8"><title>Partnership to Sales audit — October 16, 2026</title><style>body{font:16px/1.5 system-ui;max-width:1100px;margin:40px auto;padding:0 20px;color:#182638;background:#f6f8fb}article,section{background:white;padding:22px;margin:18px 0;border:1px solid #dbe2ec;border-radius:12px}h1{font-size:32px}h2{font-size:21px}input{padding:12px;width:95%;font:inherit}table{border-collapse:collapse;width:100%}td,th{text-align:left;border-bottom:1px solid #ddd;padding:10px;vertical-align:top}.id{font-size:11px;overflow-wrap:anywhere;color:#596879}.muted{color:#596879}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.5 system-ui}summary{cursor:pointer;padding:7px 0}.stats{font-weight:bold} @media print{input{display:none}article{break-inside:avoid}}</style><h1>Is the partnership-to-Sales system working?</h1><p>Audit window: September 16–October 16, 2026, through approximately 12:23 p.m. Eastern. Later update checks are separately timestamped. Internal report; contains customer communications.</p><section><h2>Finding</h2><p>Yes, outreach produces real enquiries and paid bookings. No, the current CRM cannot reliably prove that every enquiry was correctly handled or closed. Duplicate records, generic partner replies promoted into Sales, wrong dates, context resets and unresolved outcomes distort the funnel.</p><p>Two October 30 bookings have recorded deposits: Jesse $932.25 and Moe $502.50, combined $1,434.75 against quoted totals of $4,782.50. These are CRM payment records, not a new bank reconciliation. Mary and Lily have service-performance evidence but stale pipeline stages; Mary has an unresolved bolts complaint.</p><p>Five recipient/service-decline losses are verified: Alexei, Lynn, Raj, Sally and Blue Door. Sandhu is marked lost without verified recipient loss evidence. Pooja is at risk and near a competitor booking, not definitively lost. Omid appears resolved elsewhere but the terse reply needs caution. No-response is not automatically a loss.</p><p>Urgent review: Diamond and Ali Sales contact; Tahera draft quote; Naveen missed callback/context; Lilly unresolved installation; Heather/Lisa past requested windows; Moe Fakih missing customer linkage; Candice/Harsharn potential introductions; Terry date correction; Mary service recovery. Waiting for a client introduction or requested pause is not automatically a missed Sales task.</p></section>'''
page+=f'<section><h2>Reviewed cohort</h2><p>{len(rows)} distinct named enquiries or potential referral signals reviewed, including one withdrawn mistaken-recipient request (Alfonso). This is not {len(rows)} booked or fully qualified moves. Julie/Jesse and phone duplicates are consolidated.</p><table><tr><th>Evidence-based outcome</th><th>Count</th></tr>'+''.join(f'<tr><td>{esc(k)}</td><td>{v}</td></tr>' for k,v in counts.items())+'</table></section>'
page+='''<section><h2>Method and limitations</h2><p>Screened all 1,415 Sales records, 33,108 partnership contacts, 24,060 last-30-day partnership touches, 2,157 Sales SMS records, 317 call recordings, 25 referral rows, 2,366 tasks, 344 quotes and 960 stored Sales emails. Fetched 849 full-history touches for candidate/exception contacts. Matched explicit referral IDs, relationship IDs and normalized phone numbers, then reviewed substantive messages and available call transcripts. 120 recent Sales records matched partnership candidates; the full CSV retains every matched record and exclusions.</p><p>Separate reverse screening of inbound partnership conversations found Candice and Harsharn without a customer/Sales handoff. General rate requests and potential partnerships (including AURA, H2M and Studio 92) are not counted as individual moving jobs. July enquiries imported September 17 are not new September leads. Destination-generated realtor prospects are outbound relationship leads, not inbound referred customers.</p><p>Sales SMS table alone does not reliably identify sender; this report attributes named reps only when message/call content does. Call records/logs can duplicate the same call; no raw call-count conversion claim is made. Missing transcript, unlinked customer identity, offline calls, external email and unnamed referrals remain visibility gaps. This is a complete review of the identified cohort, not a guarantee that every unrecorded referral can be recovered. Evidence takes precedence over generated summaries and CRM stage. Report does not silently edit stages, merge records or book jobs.</p></section><input id="filter" placeholder="Search by name or outcome"><div id="people">'''+cards+'</div><section><h2>Other matched Sales records: exclusion / contamination review</h2><p>These records are retained for audit completeness; they are not silently counted as new moving opportunities or losses.</p><table><tr><th>Name / partner</th><th>CRM stage</th><th>Reason</th><th>Sales ID</th></tr>'+ex+'</table></section><script>document.getElementById("filter").addEventListener("input",e=>{for(const a of document.querySelectorAll("article"))a.hidden=!a.dataset.search.toLowerCase().includes(e.target.value.toLowerCase())})</script></html>'
(p/'report.html').write_text(page)
(p/'summary.json').write_text(json.dumps(dict(reviewed=len(rows),matched_sales_records=len(joined),excluded_records=len(excluded),counts=counts),indent=2))
print((p/'summary.json').read_text())
